package io.github.diodeme.ji.host;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import io.github.diodeme.ji.ai.Content;
import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiException;
import io.github.diodeme.ji.session.model.CanonicalSessionState;
import io.github.diodeme.ji.session.tree.SessionDocument;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.OptionalLong;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;

/** Shared contract suite for HostStore implementations. */
public abstract class HostStoreTck {
    private static final Instant NOW = Instant.parse("2026-09-04T00:00:00Z");
    private static final ModelRef MODEL = new ModelRef("faux", "model");

    protected abstract HostStore createStore();

    @Test
    final void acceptanceSequenceIsSharedContiguousAndIdempotent() {
        try (HostStore store = newSession()) {
            HostStore.Reservation first = store.reserve("session-1", "command-1", "hash-1", "run-1", 0);
            HostStore.QueueAcceptance second = store.enqueue(
                    "session-1", "command-2", "hash-2", "queue-2",
                    "desktop", List.of("two"), List.of());
            HostStore.Reservation third = store.reserve("session-1", "command-3", "hash-3", "run-3", 0);

            assertAll(
                    () -> assertEquals(1, first.acceptedSeq()),
                    () -> assertEquals(2, second.acceptedSeq()),
                    () -> assertEquals(3, third.acceptedSeq()),
                    () -> assertEquals(first,
                            store.reserve("session-1", "command-1", "hash-1", "replacement-run", 0)),
                    () -> assertEquals(second,
                            store.enqueue("session-1", "command-2", "hash-2", "replacement-queue",
                                    "phone", List.of("ignored"), List.of())));

            JiException conflict = assertThrows(JiException.class,
                    () -> store.reserve("session-1", "command-1", "different", "run-1", 0));
            assertAll(
                    () -> assertEquals(ErrorCode.COMMAND_PAYLOAD_CONFLICT, conflict.error().code()),
                    () -> assertEquals("command-1", conflict.error().parameters().get("commandId")),
                    () -> assertEquals("hash-1", conflict.error().parameters().get("existingPayloadSha256")),
                    () -> assertEquals("different", conflict.error().parameters().get("suppliedPayloadSha256")),
                    () -> assertEquals(first.acceptedSeq(), store.command("session-1", "command-1", "hash-1")
                            .orElseThrow().acceptedSeq()));
        }
    }

    @Test
    final void enqueueAtomicallyPublishesJournalQueueEventAndSnapshot() {
        try (HostStore store = newSession()) {
            HostStore.Snapshot before = store.snapshot("session-1");
            HostStore.QueueAcceptance accepted = store.enqueue(
                    "session-1", "command-1", "hash-1", "queue-1",
                    "desktop", List.of("prompt"), List.of("artifact-1"));

            HostStore.CommandRecord command = store.command("session-1", "command-1", "hash-1").orElseThrow();
            FollowUpQueue queue = store.queue("session-1");
            HostStore.Snapshot snapshot = store.snapshot("session-1");
            List<HostStore.DurableEvent> events = store.replay("session-1", 0);

            assertAll(
                    () -> assertEquals(0, before.revision()),
                    () -> assertEquals(1, accepted.acceptedSeq()),
                    () -> assertEquals(1, accepted.queueRevision()),
                    () -> assertEquals(HostStore.Status.QUEUED, accepted.status()),
                    () -> assertEquals(accepted.acceptedSeq(), command.acceptedSeq()),
                    () -> assertEquals(accepted.resultRef(), command.resultRef()),
                    () -> assertEquals(HostStore.Status.QUEUED, command.status()),
                    () -> assertTrue(command.commit().isEmpty()),
                    () -> assertEquals(1, queue.revision()),
                    () -> assertEquals(1, queue.items().size()),
                    () -> assertEquals(accepted.acceptedSeq(), queue.items().getFirst().acceptedSeq()),
                    () -> assertEquals(1, snapshot.revision()),
                    () -> assertEquals(1, snapshot.baseEventSeq()),
                    () -> assertEquals(1, events.size()),
                    () -> assertEquals(1, events.getFirst().eventSeq()),
                    () -> assertEquals(snapshot.revision(), events.getFirst().snapshotRevision()),
                    () -> assertEquals("queue.changed", events.getFirst().eventType()),
                    () -> assertArrayEquals(snapshot.payload(), events.getFirst().payload()));
        }
    }

    @Test
    final void unifiedPromptAcceptanceStartsWhenIdleAndQueuesWhenActive() {
        try (HostStore store = newSession()) {
            HostStore.PromptAcceptance first = store.acceptPrompt(
                    "session-1", "command-1", "hash-1", "run-1", 0,
                    "desktop", List.of("one"), List.of());
            SessionDocument running = store.update("session-1", 0,
                    document -> document.startRun(runStart("run-1")));
            HostStore.PromptAcceptance second = store.acceptPrompt(
                    "session-1", "command-2", "hash-2", "run-2", running.revision(),
                    "phone", List.of("two"), List.of("artifact-2"));
            HostStore.PromptAcceptance retry = store.acceptPrompt(
                    "session-1", "command-2", "hash-2", "replacement", 0,
                    "other-client", List.of("ignored"), List.of());

            assertAll(
                    () -> assertEquals(1, first.acceptedSeq()),
                    () -> assertEquals(HostStore.Status.RESERVED, first.status()),
                    () -> assertTrue(first.startRequired()),
                    () -> assertEquals(2, second.acceptedSeq()),
                    () -> assertEquals(HostStore.Status.QUEUED, second.status()),
                    () -> assertFalse(second.startRequired()),
                    () -> assertEquals(second, retry),
                    () -> assertEquals(List.of("two"), store.queue("session-1").items().getFirst().content()),
                    () -> assertEquals("phone", store.queue("session-1").items().getFirst().clientId()),
                    () -> assertEquals(HostStore.Status.QUEUED,
                            store.command("session-1", "command-2", "hash-2").orElseThrow().status()));
        }
    }

    @Test
    final void queueMutationsAdvanceIndependentRevisionAndContiguousDeliveryOnce() {
        try (HostStore store = newSession()) {
            store.enqueue("session-1", "command-1", "hash-1", "queue-1",
                    "desktop", List.of("one"), List.of());
            store.enqueue("session-1", "command-2", "hash-2", "queue-2",
                    "phone", List.of("two"), List.of());

            FollowUpQueue reordered = store.reorderQueue("session-1", List.of("command-2", "command-1"), 2);
            FollowUpQueue promoted = store.promote("session-1", "command-1", 3);
            List<HostStore.DurableEvent> events = store.replay("session-1", 0);
            HostStore.Snapshot snapshot = store.snapshot("session-1");

            assertAll(
                    () -> assertEquals(3, reordered.revision()),
                    () -> assertEquals(List.of(2L, 1L), reordered.items().stream()
                            .map(FollowUpQueue.Item::acceptedSeq).toList()),
                    () -> assertEquals(4, promoted.revision()),
                    () -> assertEquals(FollowUpQueue.Kind.STEER, promoted.items().getFirst().kind()),
                    () -> assertEquals(1, promoted.items().getFirst().acceptedSeq()),
                    () -> assertEquals(List.of(1L, 2L, 3L, 4L), events.stream()
                            .map(HostStore.DurableEvent::eventSeq).toList()),
                    () -> assertEquals(List.of(1L, 2L, 3L, 4L), events.stream()
                            .map(HostStore.DurableEvent::snapshotRevision).toList()),
                    () -> assertEquals(4, snapshot.revision()),
                    () -> assertEquals(4, snapshot.baseEventSeq()),
                    () -> assertArrayEquals(snapshot.payload(), events.getLast().payload()),
                    () -> assertEquals(1, store.command("session-1", "command-1", "hash-1")
                            .orElseThrow().acceptedSeq()),
                    () -> assertEquals(2, store.command("session-1", "command-2", "hash-2")
                            .orElseThrow().acceptedSeq()));
        }
    }

    @Test
    final void staleQueueMutationsAreStructuredAndLeaveEveryFactUnchanged() {
        try (HostStore store = newSession()) {
            store.enqueue("session-1", "command-1", "hash-1", "queue-1",
                    "desktop", List.of("one"), List.of());
            store.enqueue("session-1", "command-2", "hash-2", "queue-2",
                    "phone", List.of("two"), List.of());
            FollowUpQueue beforeQueue = store.queue("session-1");
            HostStore.Snapshot beforeSnapshot = store.snapshot("session-1");
            List<HostStore.DurableEvent> beforeEvents = store.replay("session-1", 0);

            List<RuntimeException> failures = List.of(
                    assertThrows(RuntimeException.class,
                            () -> store.reorderQueue("session-1", List.of("command-2", "command-1"), 1)),
                    assertThrows(RuntimeException.class,
                            () -> store.promote("session-1", "command-1", 1)),
                    assertThrows(RuntimeException.class,
                            () -> store.remove("session-1", "command-1", "desktop", 1)),
                    assertThrows(RuntimeException.class,
                            () -> store.resumeQueue("session-1", 1)));

            assertQueueAndDeliveryUnchanged(store, beforeQueue, beforeSnapshot, beforeEvents);
            assertAll(failures.stream().map(failure -> () -> assertQueueConflict(failure)));
        }
    }

    @Test
    final void removeCancelsJournalAndReturnsDraftOnlyToRequestingClient() {
        try (HostStore store = newSession()) {
            HostStore.QueueAcceptance accepted = store.enqueue(
                    "session-1", "command-1", "hash-1", "queue-1",
                    "desktop", List.of("original"), List.of("artifact-1"));
            FollowUpQueue.Removed removed = store.remove("session-1", "command-1", "phone", 1);
            HostStore.CommandRecord command = store.command("session-1", "command-1", "hash-1").orElseThrow();

            assertAll(
                    () -> assertTrue(removed.queue().items().isEmpty()),
                    () -> assertEquals(2, removed.queue().revision()),
                    () -> assertEquals("phone", removed.draft().clientId()),
                    () -> assertEquals(List.of("original"), removed.draft().content()),
                    () -> assertEquals(List.of("artifact-1"), removed.draft().attachments()),
                    () -> assertEquals(HostStore.Status.CANCELLED, command.status()),
                    () -> assertEquals(accepted.acceptedSeq(), command.acceptedSeq()),
                    () -> assertEquals(2, store.snapshot("session-1").revision()),
                    () -> assertEquals(2, store.replay("session-1", 0).size()),
                    () -> assertEquals(HostStore.Status.CANCELLED,
                            store.enqueue("session-1", "command-1", "hash-1", "replacement",
                                    "desktop", List.of("replacement"), List.of()).status()),
                    () -> assertTrue(store.queue("session-1").items().isEmpty()));
        }
    }

    @Test
    final void claimedFollowUpCanBeRolledBackToQueueHeadWithoutChangingAcceptanceIdentity() {
        try (HostStore store = newSession()) {
            store.enqueue("session-1", "command-1", "hash-1", "run-1",
                    "desktop", List.of("one"), List.of());
            store.enqueue("session-1", "command-2", "hash-2", "run-2",
                    "phone", List.of("two"), List.of());

            HostStore.ClaimedPrompt claim = store.claimNextPrompt("session-1").orElseThrow();
            assertAll(
                    () -> assertEquals("command-1", claim.item().commandId()),
                    () -> assertEquals(1, claim.item().acceptedSeq()),
                    () -> assertEquals(HostStore.Status.RESERVED,
                            store.command("session-1", "command-1", "hash-1").orElseThrow().status()),
                    () -> assertEquals(List.of("command-2"), store.queue("session-1").items().stream()
                            .map(FollowUpQueue.Item::commandId).toList()));

            store.rollbackClaim("session-1", claim);
            assertAll(
                    () -> assertEquals(List.of("command-1", "command-2"),
                            store.queue("session-1").items().stream()
                                    .map(FollowUpQueue.Item::commandId).toList()),
                    () -> assertEquals(List.of(1L, 2L), store.queue("session-1").items().stream()
                            .map(FollowUpQueue.Item::acceptedSeq).toList()),
                    () -> assertEquals(HostStore.Status.QUEUED,
                            store.command("session-1", "command-1", "hash-1").orElseThrow().status()),
                    () -> assertEquals(4, store.queue("session-1").revision()),
                    () -> assertEquals(4, store.snapshot("session-1").revision()));
        }
    }

    @Test
    final void steerBoundaryInjectsAtMostOneInPromotionOrderAndNeverRequeuesAfterInjection() {
        try (HostStore store = newSession()) {
            store.enqueue("session-1", "command-1", "hash-1", "run-1",
                    "desktop", List.of("one"), List.of());
            store.enqueue("session-1", "command-2", "hash-2", "run-2",
                    "phone", List.of("two"), List.of());
            store.promote("session-1", "command-2", 2);
            store.promote("session-1", "command-1", 3);

            var firstInput = new AtomicReference<io.github.diodeme.ji.session.tree.SessionInputCoordinator.QueuedInput>();
            SessionDocument first = store.continueWithSteer("session-1", 0, (document, input) -> {
                firstInput.set(input);
                return document.setName(Optional.of("after-first-steer"));
            }).orElseThrow();

            assertAll(
                    () -> assertEquals("command-2", firstInput.get().commandId()),
                    () -> assertEquals(2, firstInput.get().acceptedSeq()),
                    () -> assertEquals(List.of("command-1"), store.queue("session-1").items().stream()
                            .map(FollowUpQueue.Item::commandId).toList()),
                    () -> assertEquals(FollowUpQueue.Kind.STEER, store.queue("session-1").items().getFirst().kind()),
                    () -> assertEquals(HostStore.Status.INJECTED,
                            store.command("session-1", "command-2", "hash-2").orElseThrow().status()));

            var secondInput = new AtomicReference<io.github.diodeme.ji.session.tree.SessionInputCoordinator.QueuedInput>();
            store.continueWithSteer("session-1", first.revision(), (document, input) -> {
                secondInput.set(input);
                return document.setName(Optional.of("after-second-steer"));
            }).orElseThrow();

            assertAll(
                    () -> assertEquals("command-1", secondInput.get().commandId()),
                    () -> assertEquals(1, secondInput.get().acceptedSeq()),
                    () -> assertTrue(store.queue("session-1").items().isEmpty()),
                    () -> assertEquals(HostStore.Status.INJECTED,
                            store.command("session-1", "command-1", "hash-1").orElseThrow().status()),
                    () -> assertEquals(List.of(1L, 2L, 3L, 4L, 5L, 6L), store.replay("session-1", 0).stream()
                            .map(HostStore.DurableEvent::eventSeq).toList()));
        }
    }

    @Test
    final void preInjectionFailureReturnsIrreversibleSteerAtHeadWithOneRevisionAdvance() {
        try (HostStore store = newSession()) {
            store.enqueue("session-1", "command-1", "hash-1", "run-1",
                    "desktop", List.of("one"), List.of());
            store.enqueue("session-1", "command-2", "hash-2", "run-2",
                    "phone", List.of("two"), List.of());
            store.promote("session-1", "command-2", 2);
            long beforeRevision = store.queue("session-1").revision();

            assertThrows(InjectedFailure.class,
                    () -> store.continueWithSteer("session-1", 0, (document, input) -> {
                        throw new InjectedFailure();
                    }));

            FollowUpQueue queue = store.queue("session-1");
            assertAll(
                    () -> assertEquals(beforeRevision + 1, queue.revision()),
                    () -> assertEquals(List.of("command-2", "command-1"), queue.items().stream()
                            .map(FollowUpQueue.Item::commandId).toList()),
                    () -> assertEquals(FollowUpQueue.Kind.STEER, queue.items().getFirst().kind()),
                    () -> assertEquals(HostStore.Status.QUEUED,
                            store.command("session-1", "command-2", "hash-2").orElseThrow().status()),
                    () -> assertEquals(0, store.load("session-1").orElseThrow().revision()),
                    () -> assertEquals(4, store.snapshot("session-1").revision()),
                    () -> assertEquals(4, store.snapshot("session-1").baseEventSeq()));
        }
    }

    @Test
    final void abortAtomicallyPausesQueueAndOnlyExplicitResumeRestartsIt() {
        try (HostStore store = newSession()) {
            store.reserve("session-1", "command-1", "hash-1", "run-1", 0);
            SessionDocument running = store.update("session-1", 0,
                    document -> document.startRun(runStart("run-1")));
            store.enqueue("session-1", "command-2", "hash-2", "queue-2",
                    "phone", List.of("later"), List.of());

            SessionDocument cancelling = store.update("session-1", running.revision(),
                    document -> document.requestAbort("run-1", 0));
            FollowUpQueue paused = store.queue("session-1");
            HostStore.Snapshot pausedSnapshot = store.snapshot("session-1");

            assertAll(
                    () -> assertEquals(2, cancelling.revision()),
                    () -> assertEquals(CanonicalSessionState.RunStatus.CANCELLING,
                            cancelling.execution().activeRun().orElseThrow().status()),
                    () -> assertTrue(paused.paused()),
                    () -> assertEquals(2, paused.revision()),
                    () -> assertEquals(3, pausedSnapshot.revision()),
                    () -> assertEquals(3, pausedSnapshot.baseEventSeq()),
                    () -> assertTrue(new String(pausedSnapshot.payload(), java.nio.charset.StandardCharsets.UTF_8)
                            .contains("\"queuePaused\":true")));

            FollowUpQueue resumed = store.resumeQueue("session-1", paused.revision());
            assertAll(
                    () -> assertFalse(resumed.paused()),
                    () -> assertEquals(3, resumed.revision()),
                    () -> assertEquals(4, store.snapshot("session-1").revision()),
                    () -> assertEquals(List.of(1L, 2L, 3L, 4L), store.replay("session-1", 0).stream()
                            .map(HostStore.DurableEvent::eventSeq).toList()));
        }
    }

    @Test
    final void terminalCommitAtomicallyAdvancesCanonicalJournalEventAndSnapshot() {
        try (HostStore store = newSession()) {
            HostStore.Reservation reservation = store.reserve(
                    "session-1", "command-1", "hash-1", "run-1", 0);
            SessionDocument running = store.update("session-1", 0,
                    document -> document.startRun(runStart("run-1")));
            SessionDocument terminal = store.update("session-1", running.revision(),
                    document -> document.finishRun(runCompletion("run-1")));

            HostStore.CommandRecord command = store.command("session-1", "command-1", "hash-1").orElseThrow();
            HostStore.Commit commit = command.commit().orElseThrow();
            HostStore.Snapshot snapshot = store.snapshot("session-1");
            List<HostStore.DurableEvent> events = store.replay("session-1", 0);

            assertAll(
                    () -> assertEquals(terminal, store.load("session-1").orElseThrow()),
                    () -> assertEquals(HostStore.Status.COMPLETED, command.status()),
                    () -> assertEquals(reservation.acceptedSeq(), commit.acceptedSeq()),
                    () -> assertEquals(reservation.resultRef(), commit.resultRef()),
                    () -> assertEquals(2, commit.eventSeq()),
                    () -> assertEquals(2, commit.snapshotRevision()),
                    () -> assertEquals(commit.snapshotRevision(), snapshot.revision()),
                    () -> assertEquals(commit.eventSeq(), snapshot.baseEventSeq()),
                    () -> assertEquals(2, events.size()),
                    () -> assertEquals(commit.eventSeq(), events.getLast().eventSeq()),
                    () -> assertArrayEquals(snapshot.payload(), events.getLast().payload()),
                    () -> assertTrue(terminal.execution().activeRun().isEmpty()),
                    () -> assertEquals(CanonicalSessionState.RunOutcome.COMPLETED,
                            terminal.execution().completedRuns().getLast().outcome().orElseThrow()));
        }
    }

    @Test
    final void nonterminalCanonicalCommitAtomicallyPublishesDurableSnapshot() {
        try (HostStore store = newSession()) {
            HostStore.Snapshot before = store.snapshot("session-1");
            SessionDocument renamed = store.update("session-1", 0,
                    document -> document.setName(Optional.of("renamed")));

            HostStore.Snapshot after = store.snapshot("session-1");
            List<HostStore.DurableEvent> events = store.replay("session-1", before.baseEventSeq());
            assertAll(
                    () -> assertEquals(1, renamed.revision()),
                    () -> assertEquals(before.revision() + 1, after.revision()),
                    () -> assertEquals(before.baseEventSeq() + 1, after.baseEventSeq()),
                    () -> assertEquals(1, events.size()),
                    () -> assertEquals("session.snapshot", events.getFirst().eventType()),
                    () -> assertEquals(after.revision(), events.getFirst().snapshotRevision()),
                    () -> assertArrayEquals(after.payload(), events.getFirst().payload()));
        }
    }

    @Test
    final void injectedTransitionFailureLeavesCanonicalAndHostFactsWhollyBefore() {
        try (HostStore store = newSession()) {
            store.reserve("session-1", "command-1", "hash-1", "run-1", 0);
            SessionDocument running = store.update("session-1", 0,
                    document -> document.startRun(runStart("run-1")));
            FollowUpQueue beforeQueue = store.queue("session-1");
            HostStore.Snapshot beforeSnapshot = store.snapshot("session-1");
            List<HostStore.DurableEvent> beforeEvents = store.replay("session-1", 0);

            assertThrows(InjectedFailure.class, () -> store.update("session-1", running.revision(), document -> {
                document.finishRun(runCompletion("run-1"));
                throw new InjectedFailure();
            }));

            HostStore.CommandRecord command = store.command("session-1", "command-1", "hash-1").orElseThrow();
            assertAll(
                    () -> assertEquals(running, store.load("session-1").orElseThrow()),
                    () -> assertEquals(HostStore.Status.RESERVED, command.status()),
                    () -> assertTrue(command.commit().isEmpty()));
            assertQueueAndDeliveryUnchanged(store, beforeQueue, beforeSnapshot, beforeEvents);
        }
    }

    @Test
    final void canonicalEffectAndReservationRecoveryDoNotConsumeNewAcceptanceIdentity() {
        try (HostStore store = newSession()) {
            SessionDocument renamed = store.update("session-1", 0,
                    document -> document.setName(Optional.of("renamed")));
            HostStore.Reservation first = store.reserve(
                    "session-1", "command-1", "hash-1", "run-1", renamed.revision());
            store.release("session-1", "command-1", "hash-1", "run-1");
            HostStore.Reservation retry = store.reserve(
                    "session-1", "command-1", "hash-1", "ignored", renamed.revision());
            HostStore.QueueAcceptance second = store.enqueue(
                    "session-1", "command-2", "hash-2", "queue-2",
                    "desktop", List.of("two"), List.of());

            assertAll(
                    () -> assertEquals(1, first.acceptedSeq()),
                    () -> assertEquals(first.acceptedSeq(), retry.acceptedSeq()),
                    () -> assertEquals(first.resultRef(), retry.resultRef()),
                    () -> assertEquals(HostStore.Status.RESERVED, retry.status()),
                    () -> assertEquals(2, second.acceptedSeq()));
        }
    }

    private HostStore newSession() {
        HostStore store = createStore();
        store.create("session-1", MODEL, "workspace", NOW);
        return store;
    }

    private static SessionDocument.RunStart runStart(String runId) {
        Message prompt = new Message("message-" + runId, Message.Role.USER,
                List.of(new Content.Text("prompt")), NOW);
        return new SessionDocument.RunStart(
                runId, "turn-1", "attempt-1", "result-entry-1", prompt,
                "operation-start-1", "attempt-record-1", NOW);
    }

    private static SessionDocument.RunCompletion runCompletion(String runId) {
        return new SessionDocument.RunCompletion(
                runId, 0, "turn-1", 0, "attempt-1", 0,
                List.of(new Message("assistant-1", Message.Role.ASSISTANT,
                        List.of(new Content.Text("done")), NOW)),
                new Usage(2, 1, 0, 0, 0), CanonicalSessionState.RunOutcome.COMPLETED,
                "usage-record-1", "operation-finish-1", NOW.plusSeconds(1));
    }

    private static void assertQueueConflict(RuntimeException failure) {
        JiException structured = assertInstanceOf(JiException.class, failure);
        assertAll(
                () -> assertEquals(ErrorCode.QUEUE_REVISION_CONFLICT, structured.error().code()),
                () -> assertEquals(Map.of("expectedRevision", "1", "currentRevision", "2"),
                        structured.error().parameters()),
                () -> assertEquals(OptionalLong.of(2), structured.error().currentRevision()));
    }

    private static void assertQueueAndDeliveryUnchanged(
            HostStore store,
            FollowUpQueue beforeQueue,
            HostStore.Snapshot beforeSnapshot,
            List<HostStore.DurableEvent> beforeEvents) {
        FollowUpQueue afterQueue = store.queue("session-1");
        HostStore.Snapshot afterSnapshot = store.snapshot("session-1");
        List<HostStore.DurableEvent> afterEvents = store.replay("session-1", 0);
        assertAll(
                () -> assertEquals(beforeQueue, afterQueue),
                () -> assertEquals(beforeSnapshot.revision(), afterSnapshot.revision()),
                () -> assertEquals(beforeSnapshot.baseEventSeq(), afterSnapshot.baseEventSeq()),
                () -> assertArrayEquals(beforeSnapshot.payload(), afterSnapshot.payload()),
                () -> assertEquals(beforeEvents.size(), afterEvents.size()),
                () -> assertEquals(beforeEvents.stream().map(HostStore.DurableEvent::eventSeq).toList(),
                        afterEvents.stream().map(HostStore.DurableEvent::eventSeq).toList()));
    }

    private static final class InjectedFailure extends RuntimeException {
        private static final long serialVersionUID = 1L;
    }
}

