    protected abstract HostStore createStore();

    @Test
    final void acceptanceSequenceIsSharedContiguousAndIdempotent() {
        try (HostStore store = newSession()) {
            HostStore.PromptAcceptance first = accept(
                    store, "command-1", "hash-1", "run-1", 0, "desktop", "one");
            HostStore.PromptAcceptance second = accept(
                    store, "command-2", "hash-2", "run-2", 0, "desktop", "two");
            HostStore.PromptAcceptance third = accept(
                    store, "command-3", "hash-3", "run-3", 0, "phone", "three");
            HostStore.PromptAcceptance firstRetry = accept(
                    store, "command-1", "hash-1", "replacement-run", 0, "phone", "ignored");
            HostStore.PromptAcceptance secondRetry = accept(
                    store, "command-2", "hash-2", "replacement-run", 0, "phone", "ignored");

            assertAll(
                    () -> assertEquals(1, first.acceptedSeq()),
                    () -> assertEquals(2, second.acceptedSeq()),
                    () -> assertEquals(3, third.acceptedSeq()),
                    () -> assertEquals(first.acceptedSeq(), firstRetry.acceptedSeq()),
                    () -> assertEquals(first.resultRef(), firstRetry.resultRef()),
                    () -> assertEquals(first.status(), firstRetry.status()),
                    () -> assertEquals(second.acceptedSeq(), secondRetry.acceptedSeq()),
                    () -> assertEquals(second.resultRef(), secondRetry.resultRef()),
                    () -> assertEquals(second.status(), secondRetry.status()));

            JiException conflict = assertThrows(JiException.class,
                    () -> accept(store, "command-1", "different", "run-1", 0, "desktop", "one"));
            assertAll(
                    () -> assertEquals(ErrorCode.COMMAND_PAYLOAD_CONFLICT, conflict.error().code()),
                    () -> assertEquals("command-1", conflict.error().parameters().get("commandId")),
                    () -> assertEquals("hash-1", conflict.error().parameters().get("existingPayloadSha256")),
                    () -> assertEquals("different", conflict.error().parameters().get("suppliedPayloadSha256")),
                    () -> assertEquals(first.acceptedSeq(), store.command("session-1", "command-1", "hash-1")
                            .orElseThrow().acceptedSeq()));
        }
    }

    @Test
    final void enqueueAtomicallyPublishesJournalQueueEventAndSnapshot() {
        try (HostStore store = newSession()) {
            reserveBlocker(store);
            HostStore.Snapshot before = store.snapshot("session-1");
            HostStore.PromptAcceptance accepted = store.acceptPrompt(
                    "session-1", "command-1", "hash-1", "run-1", 0,
                    "desktop", List.of("prompt"), List.of("artifact-1"));

            HostStore.CommandRecord command = store.command("session-1", "command-1", "hash-1").orElseThrow();
            FollowUpQueue queue = store.queue("session-1");
            HostStore.Snapshot snapshot = store.snapshot("session-1");
            List<HostStore.DurableEvent> events = store.replay("session-1", 0);

            assertAll(
                    () -> assertEquals(0, before.revision()),
                    () -> assertEquals(2, accepted.acceptedSeq()),
                    () -> assertEquals(1, accepted.queueRevision()),
                    () -> assertEquals(HostStore.Status.QUEUED, accepted.status()),
                    () -> assertEquals(accepted.acceptedSeq(), command.acceptedSeq()),
                    () -> assertEquals(accepted.resultRef(), command.resultRef()),
                    () -> assertEquals(HostStore.Status.QUEUED, command.status()),
                    () -> assertTrue(command.commit().isEmpty()),
                    () -> assertEquals(1, queue.revision()),
                    () -> assertEquals(1, queue.items().size()),
                    () -> assertEquals(accepted.acceptedSeq(), queue.items().getFirst().acceptedSeq()),
                    () -> assertEquals(1, snapshot.revision()),
                    () -> assertEquals(1, snapshot.baseEventSeq()),
                    () -> assertEquals(1, events.size()),
                    () -> assertEquals(1, events.getFirst().eventSeq()),
                    () -> assertEquals(snapshot.revision(), events.getFirst().snapshotRevision()),
                    () -> assertEquals("queue.changed", events.getFirst().eventType()),
                    () -> assertArrayEquals(snapshot.payload(), events.getFirst().payload()));
        }
    }

    @Test
