        try (HostStore store = newSession()) {
            HostStore.PromptAcceptance first = store.acceptPrompt(
                    "session-1", "command-1", "hash-1", "run-1", 0,
                    "desktop", List.of("one"), List.of());
            SessionDocument running = store.update("session-1", 0,
                    document -> document.startRun(runStart("run-1")));
            HostStore.PromptAcceptance second = store.acceptPrompt(
                    "session-1", "command-2", "hash-2", "run-2", running.revision(),
                    "phone", List.of("two"), List.of("artifact-2"));
            HostStore.PromptAcceptance retry = store.acceptPrompt(
