    @Test
    final void queueMutationsAdvanceIndependentRevisionAndContiguousDeliveryOnce() {
        try (HostStore store = newSession()) {
            reserveBlocker(store);
            accept(store, "command-1", "hash-1", "run-1", 0, "desktop", "one");
            accept(store, "command-2", "hash-2", "run-2", 0, "phone", "two");

            FollowUpQueue reordered = store.reorderQueue("session-1", List.of("command-2", "command-1"), 2);
            FollowUpQueue promoted = store.promote("session-1", "command-1", 3);
            List<HostStore.DurableEvent> events = store.replay("session-1", 0);
            HostStore.Snapshot snapshot = store.snapshot("session-1");

            assertAll(
                    () -> assertEquals(3, reordered.revision()),
                    () -> assertEquals(List.of(3L, 2L), reordered.items().stream()
                            .map(FollowUpQueue.Item::acceptedSeq).toList()),
                    () -> assertEquals(4, promoted.revision()),
                    () -> assertEquals(FollowUpQueue.Kind.STEER, promoted.items().getFirst().kind()),
                    () -> assertEquals(2, promoted.items().getFirst().acceptedSeq()),
                    () -> assertEquals(List.of(1L, 2L, 3L, 4L), events.stream()
                            .map(HostStore.DurableEvent::eventSeq).toList()),
                    () -> assertEquals(List.of(1L, 2L, 3L, 4L), events.stream()
                            .map(HostStore.DurableEvent::snapshotRevision).toList()),
                    () -> assertEquals(4, snapshot.revision()),
                    () -> assertEquals(4, snapshot.baseEventSeq()),
                    () -> assertArrayEquals(snapshot.payload(), events.getLast().payload()),
                    () -> assertEquals(2, store.command("session-1", "command-1", "hash-1")
                            .orElseThrow().acceptedSeq()),
                    () -> assertEquals(3, store.command("session-1", "command-2", "hash-2")
                            .orElseThrow().acceptedSeq()));
        }
    }

