    @Test
    final void steerBoundaryInjectsAtMostOneInPromotionOrderAndNeverRequeuesAfterInjection() {
        try (HostStore store = newSession()) {
            reserveBlocker(store);
            accept(store, "command-1", "hash-1", "run-1", 0, "desktop", "one");
            accept(store, "command-2", "hash-2", "run-2", 0, "phone", "two");
            store.promote("session-1", "command-2", 2);
            store.promote("session-1", "command-1", 3);

            var firstInput = new AtomicReference<io.github.diodeme.ji.session.tree.SessionInputCoordinator.QueuedInput>();
            SessionDocument first = store.continueWithSteer("session-1", 0, (document, input) -> {
                firstInput.set(input);
                return document.setName(Optional.of("after-first-steer"));
            }).orElseThrow();

            assertAll(
                    () -> assertEquals("command-2", firstInput.get().commandId()),
                    () -> assertEquals(3, firstInput.get().acceptedSeq()),
                    () -> assertEquals(List.of("command-1"), store.queue("session-1").items().stream()
                            .map(FollowUpQueue.Item::commandId).toList()),
                    () -> assertEquals(FollowUpQueue.Kind.STEER, store.queue("session-1").items().getFirst().kind()),
                    () -> assertEquals(HostStore.Status.INJECTED,
                            store.command("session-1", "command-2", "hash-2").orElseThrow().status()));

            var secondInput = new AtomicReference<io.github.diodeme.ji.session.tree.SessionInputCoordinator.QueuedInput>();
            store.continueWithSteer("session-1", first.revision(), (document, input) -> {
                secondInput.set(input);
                return document.setName(Optional.of("after-second-steer"));
            }).orElseThrow();

            assertAll(
                    () -> assertEquals("command-1", secondInput.get().commandId()),
                    () -> assertEquals(2, secondInput.get().acceptedSeq()),
                    () -> assertTrue(store.queue("session-1").items().isEmpty()),
                    () -> assertEquals(HostStore.Status.INJECTED,
                            store.command("session-1", "command-1", "hash-1").orElseThrow().status()),
                    () -> assertEquals(List.of(1L, 2L, 3L, 4L, 5L, 6L), store.replay("session-1", 0).stream()
                            .map(HostStore.DurableEvent::eventSeq).toList()));
        }
    }

    @Test
    final void preInjectionFailureReturnsIrreversibleSteerAtHeadWithOneRevisionAdvance() {
        try (HostStore store = newSession()) {
            reserveBlocker(store);
            accept(store, "command-1", "hash-1", "run-1", 0, "desktop", "one");
            accept(store, "command-2", "hash-2", "run-2", 0, "phone", "two");
            store.promote("session-1", "command-2", 2);
