                    () -> assertEquals(HostStore.Status.QUEUED,
                            store.command("session-1", "command-2", "hash-2").orElseThrow().status()),
                    () -> assertEquals(0, store.load("session-1").orElseThrow().revision()),
                    () -> assertEquals(4, store.snapshot("session-1").revision()),
                    () -> assertEquals(4, store.snapshot("session-1").baseEventSeq()));
        }
    }

    @Test
    final void abortAtomicallyPausesQueueAndOnlyExplicitResumeRestartsIt() {
        try (HostStore store = newSession()) {
            accept(store, "command-1", "hash-1", "run-1", 0, "desktop", "one");
            SessionDocument running = store.update("session-1", 0,
                    document -> document.startRun(runStart("run-1")));
            accept(store, "command-2", "hash-2", "run-2", running.revision(), "phone", "later");

            SessionDocument cancelling = store.update("session-1", running.revision(),
                    document -> document.requestAbort("run-1", 0));
            FollowUpQueue paused = store.queue("session-1");
            HostStore.Snapshot pausedSnapshot = store.snapshot("session-1");

            assertAll(
                    () -> assertEquals(2, cancelling.revision()),
                    () -> assertEquals(CanonicalSessionState.RunStatus.CANCELLING,
                            cancelling.execution().activeRun().orElseThrow().status()),
                    () -> assertTrue(paused.paused()),
                    () -> assertEquals(2, paused.revision()),
                    () -> assertEquals(3, pausedSnapshot.revision()),
                    () -> assertEquals(3, pausedSnapshot.baseEventSeq()),
                    () -> assertTrue(new String(pausedSnapshot.payload(), java.nio.charset.StandardCharsets.UTF_8)
                            .contains("\"queuePaused\":true")));

            FollowUpQueue resumed = store.resumeQueue("session-1", paused.revision());
            assertAll(
                    () -> assertFalse(resumed.paused()),
                    () -> assertEquals(3, resumed.revision()),
                    () -> assertEquals(4, store.snapshot("session-1").revision()),
                    () -> assertEquals(List.of(1L, 2L, 3L, 4L), store.replay("session-1", 0).stream()
                            .map(HostStore.DurableEvent::eventSeq).toList()));
        }
    }

    @Test
    final void terminalCommitAtomicallyAdvancesCanonicalJournalEventAndSnapshot() {
        try (HostStore store = newSession()) {
            HostStore.PromptAcceptance reservation = accept(
                    store, "command-1", "hash-1", "run-1", 0, "desktop", "prompt");
            SessionDocument running = store.update("session-1", 0,
                    document -> document.startRun(runStart("run-1")));
            HostStore.Snapshot beforeTerminal = store.snapshot("session-1");
            SessionDocument terminal = store.update("session-1", running.revision(),
                    document -> document.finishRun(runCompletion("run-1")));

            HostStore.CommandRecord command = store.command("session-1", "command-1", "hash-1").orElseThrow();
            HostStore.Commit commit = command.commit().orElseThrow();
            HostStore.Snapshot snapshot = store.snapshot("session-1");
            List<HostStore.DurableEvent> events = store.replay("session-1", 0);

            assertAll(
                    () -> assertEquals(terminal, store.load("session-1").orElseThrow()),
                    () -> assertEquals(HostStore.Status.COMPLETED, command.status()),
                    () -> assertEquals(reservation.acceptedSeq(), commit.acceptedSeq()),
                    () -> assertEquals(reservation.resultRef(), commit.resultRef()),
                    () -> assertEquals(beforeTerminal.baseEventSeq() + 1, commit.eventSeq()),
                    () -> assertEquals(beforeTerminal.revision() + 1, commit.snapshotRevision()),
                    () -> assertEquals(commit.snapshotRevision(), snapshot.revision()),
                    () -> assertEquals(commit.eventSeq(), snapshot.baseEventSeq()),
                    () -> assertEquals(2, events.size()),
                    () -> assertEquals(commit.eventSeq(), events.getLast().eventSeq()),
                    () -> assertArrayEquals(snapshot.payload(), events.getLast().payload()),
                    () -> assertTrue(terminal.execution().activeRun().isEmpty()),
                    () -> assertEquals(CanonicalSessionState.RunOutcome.COMPLETED,
                            terminal.execution().completedRuns().getLast().outcome().orElseThrow()));
        }
    }

